def copy_client_settings(apps, schema_editor):
    """Move the legacy boolean/threshold settings to the new policy fields."""
    OperationType = apps.get_model("operations", "OperationType")
    BankSettings = apps.get_model("core", "BankSettings")
    base_currency = (
        BankSettings.objects.filter(pk=1).values_list("base_currency", flat=True).first() or "BYN"
    )
    for operation_type in OperationType.objects.all():
        operation_type.client_data_policy = "never"
        if operation_type.requires_client:
            if operation_type.client_id_threshold is not None and operation_type.client_id_threshold > 0:
                operation_type.client_data_policy = "threshold"
                operation_type.threshold_type = "currency"
                operation_type.threshold_value = operation_type.client_id_threshold
                operation_type.threshold_currency = base_currency
            else:
                operation_type.client_data_policy = "always"
        operation_type.save(
            update_fields=[
                "client_data_policy",
                "threshold_type",
                "threshold_value",
                "threshold_currency",
            ]
        )


def restore_client_settings(apps, schema_editor):
    """Restore the legacy fields from the new policy fields on rollback."""
    OperationType = apps.get_model("operations", "OperationType")
    for operation_type in OperationType.objects.all():
        operation_type.requires_client = operation_type.client_data_policy in {
            "always",
            "threshold",
        }
        operation_type.client_id_threshold = (
            operation_type.threshold_value
            if operation_type.client_data_policy == "threshold"
            and operation_type.threshold_type == "currency"
            else None
        )
        operation_type.save(update_fields=["requires_client", "client_id_threshold"])


